head.b:skin:
/* Variable definitions
-----------------------
<Group description="Theme Colors" selector="body">
<Variable name="bgColor" description="Page background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="surfaceColor" description="Card background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="textColor" description="Main text" type="color" default="#0f0f0f" value="#0f0f0f"/>
<Variable name="mutedColor" description="Muted text" type="color" default="#737373" value="#737373"/>
<Variable name="accentColor" description="Red accent" type="color" default="#cc0000" value="#cc0000"/>
<Variable name="borderColor" description="Borders" type="color" default="#e6e6e6" value="#e6e6e6"/>
<Variable name="darkColor" description="Header/footer black" type="color" default="#000000" value="#000000"/>
</Group>
<Group description="Fonts" selector="body">
<Variable name="bodyFont" description="Body font" type="font" default="normal normal 16px Archivo, Helvetica Neue, Helvetica, Arial, sans-serif" value="normal normal 16px Archivo, Helvetica Neue, Helvetica, Arial, sans-serif"/>
</Group>
-----------------------
*/
/* ============ Base ============ */
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:$(bgColor);color:$(textColor);font:$(bodyFont);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
a:hover{color:$(accentColor)}
img{max-width:100%;height:auto}
h1,h2,h3,h4{line-height:1.25;margin:0}
button{font:inherit;cursor:pointer}
:focus-visible{outline:2px solid $(accentColor);outline-offset:2px}
.wrap{max-width:1280px;margin:0 auto;padding:0 20px}
.skip-link{position:absolute;left:-9999px;top:0;background:$(accentColor);color:#fff;padding:10px 16px;font-weight:700;z-index:200}
.skip-link:focus{left:10px;top:10px}

/* ============ Header (CNN black bar) ============ */
.site-header{position:sticky;top:0;z-index:100;background:$(darkColor);border-bottom:3px solid $(accentColor)}
.header-inner{display:flex;align-items:center;gap:18px;min-height:56px}
.brand{flex:none}
.logo-box{display:inline-block;background:$(accentColor);color:#fff;font-size:20px;font-weight:900;letter-spacing:.04em;line-height:1;padding:9px 12px;border-radius:2px;white-space:nowrap}
.logo-box small{display:block;font-size:10px;font-weight:700;letter-spacing:.28em;margin-top:3px}
.logo-box:hover{color:#fff}
.tagline{display:none}
.main-nav{margin-left:6px;min-width:0;overflow:hidden}
.nav-list{display:flex;gap:2px;list-style:none;margin:0;padding:0}
.nav-list a{display:block;padding:8px 11px;font-size:14px;font-weight:600;color:#fff;white-space:nowrap;border-radius:3px}
.nav-list a:hover{color:#fff;background:#262626}
.header-actions{display:flex;gap:8px;align-items:center;margin-left:auto}
.header-actions .watch-link,.header-actions .listen-link{color:#fff;font-size:14px;font-weight:600;white-space:nowrap;padding:8px 6px}
.header-actions .watch-link:hover,.header-actions .listen-link:hover{color:#fff;text-decoration:underline}
.signin-btn{background:#fff;color:#000;border:0;border-radius:20px;font-weight:700;font-size:14px;padding:7px 16px;white-space:nowrap}
.signin-btn:hover{background:#e6e6e6;color:#000}
.icon-btn{background:none;border:1px solid #4d4d4d;color:#fff;width:38px;height:38px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;padding:0}
.icon-btn:hover{border-color:#fff}
.icon-btn svg{width:18px;height:18px}
#navToggle{display:none}

/* Search overlay */
.search-overlay{position:fixed;inset:0;z-index:150;background:rgba(0,0,0,.92);display:none;align-items:flex-start;justify-content:center;padding:110px 20px 20px}
.search-overlay.open{display:flex}
.search-overlay form{display:flex;width:100%;max-width:640px;gap:10px}
.search-overlay input[type=text]{flex:1;background:#1a1a1a;border:1px solid #4d4d4d;border-radius:8px;color:#fff;font-size:18px;padding:14px 16px;min-width:0}
.search-overlay input[type=text]:focus{border-color:$(accentColor);outline:none}
.search-overlay button[type=submit]{background:$(accentColor);color:#fff;border:0;border-radius:8px;font-weight:800;padding:0 22px}
.search-close{background:none;border:1px solid #4d4d4d;color:#fff;border-radius:8px;width:52px;font-size:24px;line-height:1}

/* ============ Breaking bar ============ */
.breaking-bar{background:$(accentColor);color:#fff}
.breaking-inner{display:flex;align-items:center;gap:12px;min-height:40px;padding-top:6px;padding-bottom:6px}
.breaking-tag{background:#fff;color:$(accentColor);font-size:12px;font-weight:900;letter-spacing:.12em;padding:4px 9px;border-radius:2px;white-space:nowrap;flex:0 0 auto;z-index:2}
.breaking-link{color:#fff;font-size:15px;font-weight:700;white-space:nowrap}
.breaking-link:hover{color:#fff;text-decoration:underline}
/* TV-style scrolling ticker: top 5 headlines glide right-to-left, nonstop */
.ticker-viewport{flex:1;min-width:0;overflow:hidden}
.ticker-track{display:inline-flex;white-space:nowrap;animation:ticker-scroll 45s linear infinite;will-change:transform}
.ticker-group{display:inline-flex;align-items:center;white-space:nowrap}
.ticker-sep{color:#ffd6d6;padding:0 18px;font-weight:900}
@keyframes ticker-scroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@media (prefers-reduced-motion: reduce){.ticker-track{animation:none}}

/* ============ Ad slots ============ */
.ad-slot{margin:20px 0 0;text-align:center}
.ad-slot:empty{display:none}
.ad-slot .widget{margin:0}
.ad-slot iframe{max-width:100%}
.ad-ph{border:1px dashed #c9c9c9;background:#f6f6f6;color:#8a8a8a;text-align:center;padding:16px 10px;margin:0 auto}
.ad-ph span{display:block;font-size:11px;font-weight:800;letter-spacing:.22em}
.ad-ph em{display:block;font-size:12px;font-style:normal;margin-top:4px}
.ad-728x90{max-width:728px;min-height:90px}
.ad-300x250{width:300px;max-width:100%;min-height:250px}
.ad-300x600{width:300px;max-width:100%;min-height:600px}
.ad-native{max-width:100%;min-height:120px}
.ad-slot-home-leader{margin-top:16px}

/* ============ Homepage layout: main + right rail ============ */
.home-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:28px;align-items:start;margin-top:22px}
.home-rail{position:sticky;top:78px}
.home-rail .widget{margin-bottom:26px}
.rail-head{font-size:15px;font-weight:900;letter-spacing:.1em;text-transform:uppercase;border-bottom:3px solid #000;padding-bottom:8px;margin:0 0 14px}
.rail-head::before{content:'';display:inline-block;width:8px;height:16px;background:$(accentColor);margin-right:9px;vertical-align:-2px}
.rail-head.red{color:$(accentColor);border-bottom-color:$(accentColor)}
.rail-head.red::before{background:$(accentColor)}

/* DEVELOPING list */
.dev-list{list-style:none;margin:0;padding:0}
.dev-list li{display:flex;gap:12px;padding:11px 0;border-bottom:1px solid $(borderColor)}
.dev-list li:first-child{padding-top:0}
.dev-time{flex:none;width:58px;font-size:12px;font-weight:700;color:$(accentColor);padding-top:2px}
.dev-title{font-size:15px;font-weight:700;line-height:1.35}
.dev-title a:hover{color:$(accentColor)}
.dev-title .breaking-flag{color:$(accentColor)}

/* ============ Hero ============ */
.hero{display:none;margin:0}
.hero.ready{display:block}
.hero-grid{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-rows:200px;gap:14px}
.hero-card{position:relative;overflow:hidden;background:#111}
.hero-card:first-child{grid-column:span 2;grid-row:span 2}
.hero-card a{display:block;width:100%;height:100%}
.hero-card img{width:100%;height:100%;object-fit:cover;display:block}
.hero-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.02) 30%,rgba(0,0,0,.88) 100%)}
.hero-info{position:absolute;left:0;right:0;bottom:0;padding:18px}
.hero-info h3{margin:8px 0 4px;font-size:19px;line-height:1.3;color:#fff;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.hero-card:first-child .hero-info h3{font-size:30px;-webkit-line-clamp:3}
.hero-date{color:#e6e6e6;font-size:12px;margin:0}
.hero-chip,.card-chip{display:inline-block;background:$(accentColor);color:#fff;font-size:11px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;padding:4px 8px;border-radius:2px;line-height:1.2}

/* ============ Label rows ============ */
.label-row{display:none;margin:34px 0 0}
.label-row.ready{display:block}
.row-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;border-bottom:2px solid #000;margin-bottom:16px;padding-bottom:10px}
.row-head h2,.latest-head h2{font-size:20px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}
.row-head h2::before,.latest-head h2::before{content:'';display:inline-block;width:8px;height:18px;background:$(accentColor);margin-right:10px;vertical-align:-2px}
.row-head a{font-size:13px;font-weight:700;color:$(accentColor);white-space:nowrap}
.row-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}

/* ============ Cards ============ */
.card{background:$(surfaceColor);border:1px solid $(borderColor);overflow:hidden}
.card-thumb{position:relative;display:block;aspect-ratio:16/9;overflow:hidden;background:#111}
.card-thumb img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .35s ease}
.card:hover .card-thumb img{transform:scale(1.05)}
.card-chips{position:absolute;top:8px;left:8px;z-index:2;display:flex;gap:6px;flex-wrap:wrap}
.card-info{padding:12px 14px 14px}
.card-title{font-size:16px;font-weight:700;line-height:1.35;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.card-title a:hover{color:$(accentColor)}
.card-date{font-size:12px;color:$(mutedColor);margin:8px 0 0}
.thumb-ph{width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#1a1a1a 0%,#000 55%,#3d0000 100%)}
.thumb-ph svg{width:46px;height:46px;opacity:.7}
.hero-card .thumb-ph{position:absolute;inset:0}

/* ============ Latest grid (native post loop) ============ */
.latest-head{margin:34px 0 16px;border-bottom:2px solid #000;padding-bottom:10px}
.cards-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:0 0 10px}
.empty-msg{text-align:center;color:$(mutedColor);padding:40px 0;font-size:17px}

/* ============ Content area + post page ============ */
.content-area{margin:26px 0 44px}
.item .content-area,.static_page .content-area{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:32px;align-items:start}
.post-hero{overflow:hidden;margin-bottom:22px}
.post-hero img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block}
.post-kicker{font-size:13px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:$(accentColor);margin:0 0 10px}
.post-title{font-size:38px;font-weight:900;line-height:1.15;margin:0 0 12px}
.post-meta{display:flex;flex-wrap:wrap;gap:6px 16px;color:$(mutedColor);font-size:13px;margin:0 0 20px;padding-bottom:16px;border-bottom:1px solid $(borderColor)}
.post-meta a{color:$(mutedColor)}
.post-meta a:hover{color:$(accentColor)}
.post-body{font-size:18px;line-height:1.75;overflow-wrap:break-word}
.post-body p{margin:0 0 16px}
.post-body h2{font-size:25px;font-weight:800;margin:28px 0 10px;padding-left:12px;border-left:3px solid $(accentColor)}
.post-body h3{font-size:20px;margin:24px 0 8px}
.post-body a{color:$(accentColor);text-decoration:underline}
.post-body img{border-radius:4px}
.post-body ul,.post-body ol{margin:0 0 16px;padding-left:24px}
.post-body blockquote{margin:0 0 16px;padding:12px 18px;border-left:3px solid $(accentColor);background:#f7f7f7}
.item .post-body > .separator:first-of-type{display:none}
.item .post-body > p:empty{display:none}
body.index .sidebar,body.archive .sidebar,body.error_page .sidebar{display:none}
body.item .ad-slot-home,body.static_page .ad-slot-home{display:none}
body.index .ad-slot-post,body.archive .ad-slot-post,body.error_page .ad-slot-post{display:none}
.post-labels{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}
.post-labels a{border:1px solid $(borderColor);border-radius:999px;padding:6px 13px;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#555}
.post-labels a:hover{border-color:$(accentColor);color:$(accentColor)}
.share-row{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:24px 0;padding:18px 0;border-top:1px solid $(borderColor);border-bottom:1px solid $(borderColor)}
.share-label{font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:$(mutedColor);margin-right:4px}
.share-button{border:1px solid $(borderColor);border-radius:8px;padding:8px 14px;font-size:13px;font-weight:700;color:#555}
.share-button:hover{border-color:$(accentColor);color:$(accentColor)}

/* Related posts */
.related{margin-top:34px}
.related h3{font-size:20px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;border-bottom:2px solid #000;padding-bottom:10px;margin-bottom:16px}
.related h3::before{content:'';display:inline-block;width:8px;height:18px;background:$(accentColor);margin-right:10px;vertical-align:-2px}
.related .row-grid{grid-template-columns:repeat(4,1fr)}
.related{display:none}
.related.ready{display:block}

/* Pager */
.blog-pager{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:center;margin:32px 0 0}
.blog-pager a{border:1px solid $(borderColor);border-radius:8px;padding:10px 18px;font-size:14px;font-weight:700}
.blog-pager a:hover{border-color:$(accentColor);color:$(accentColor)}
.blog-pager .home-link{color:$(mutedColor)}

/* Status message */
.status-msg h1{font-size:30px;font-weight:900;margin:26px 0 6px}

/* ============ Comments ============ */
.comments{margin-top:38px;border-top:1px solid $(borderColor);padding-top:22px}
.comments h3{font-size:20px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;margin-bottom:16px}
.comment-list{list-style:none;margin:0 0 20px;padding:0}
.comment{border:1px solid $(borderColor);border-radius:8px;padding:14px 16px;margin-bottom:12px;background:#f7f7f7}
.comment-head{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.comment-avatar{width:36px;height:36px;border-radius:50%;object-fit:cover}
.comment-author{font-weight:700;font-size:14px}
.comment-time{font-size:12px;color:$(mutedColor);margin-left:auto}
.comment-body{font-size:15px;line-height:1.7}
.comment-body p{margin:0 0 8px}
.comment-iframe{width:100%;min-height:260px;border:0}
.comments-closed{color:$(mutedColor)}

/* ============ Sidebar (post pages + home rail) ============ */
.sidebar .widget,.home-rail .widget{margin-bottom:30px}
.sidebar .widget h2,.sidebar .widget h2.title,.home-rail .widget h2{font-size:16px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;border-bottom:2px solid #000;padding-bottom:8px;margin:0 0 14px}
.sidebar ul,.home-rail ul{list-style:none;margin:0;padding:0}
.sidebar li,.home-rail li{margin-bottom:12px}
.sidebar .item-thumbnail{float:left;margin:0 10px 4px 0}
.sidebar .item-thumbnail img{display:block;border-radius:4px}
.sidebar .item-title{font-weight:700;font-size:14px;line-height:1.4}
.sidebar .item-snippet{font-size:13px;color:$(mutedColor)}
.PopularPosts .item-thumbnail{float:left;margin:0 12px 4px 0}
.PopularPosts .item-thumbnail img{width:76px;height:56px;object-fit:cover;border-radius:4px;display:block}
.PopularPosts .item-title{font-size:14px;font-weight:600;line-height:1.4}
.PopularPosts li{overflow:hidden}
.Label li{display:inline-block;margin:0 8px 8px 0}
.Label li a{border:1px solid $(borderColor);border-radius:999px;padding:5px 12px;font-size:12px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;display:inline-block}
.Label li a:hover{border-color:$(accentColor)}

/* ============ Footer ============ */
.site-footer{border-top:3px solid $(accentColor);background:$(darkColor);color:#fff;margin-top:20px}
.footer-inner{display:flex;flex-wrap:wrap;gap:24px;justify-content:space-between;padding:30px 0}
.footer-brand h3{font-size:19px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;margin:0 0 8px}
.footer-brand h3 span{color:#fff;background:$(accentColor);padding:2px 8px;border-radius:2px}
.footer-brand p{color:#b3b3b3;font-size:14px;max-width:430px;margin:0}
.footer-nav ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px 20px}
.footer-nav a{font-size:14px;font-weight:600;color:#e6e6e6}
.footer-nav a:hover{color:#fff;text-decoration:underline}
.copyright{border-top:1px solid #262626;padding:15px 0 18px;font-size:13px;color:#b3b3b3;text-align:center}

/* ============ Back to top ============ */
#toTop{position:fixed;right:18px;bottom:18px;width:44px;height:44px;border-radius:50%;background:$(accentColor);color:#fff;border:0;font-size:20px;line-height:1;opacity:0;pointer-events:none;transition:opacity .25s ease;z-index:90;padding:0}
#toTop.show{opacity:1;pointer-events:auto}

/* ============ Responsive ============ */
@media (max-width:1100px){
  .home-layout{grid-template-columns:minmax(0,1fr) 300px}
  .row-grid{grid-template-columns:repeat(3,1fr)}
  .related .row-grid{grid-template-columns:repeat(3,1fr)}
}
@media (max-width:960px){
  .home-layout{grid-template-columns:minmax(0,1fr)}
  .home-rail{position:static;display:grid;grid-template-columns:repeat(2,1fr);gap:0 28px}
  .item .content-area,.static_page .content-area{grid-template-columns:minmax(0,1fr)}
  .hero-grid{grid-template-columns:repeat(2,1fr);grid-auto-rows:180px}
  .hero-card:first-child{grid-column:span 2;grid-row:span 1}
  .hero-card:first-child .hero-info h3{font-size:24px}
  .cards-grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:860px){
  .main-nav{display:none}
  .main-nav.open{display:block;position:absolute;top:56px;left:0;right:0;background:#000;border-bottom:3px solid $(accentColor);padding:10px 20px 16px;z-index:99}
  .main-nav.open .nav-list{flex-direction:column}
  .main-nav.open .nav-list a{padding:11px 10px;font-size:15px}
  #navToggle{display:inline-flex}
  .header-inner{position:relative}
  .header-actions .watch-link,.header-actions .listen-link{display:none}
}
@media (max-width:700px){
  .row-grid{grid-template-columns:repeat(2,1fr)}
  .related .row-grid{grid-template-columns:repeat(2,1fr)}
  .post-title{font-size:29px}
  .post-body{font-size:17px}
  .home-rail{grid-template-columns:1fr}
}
@media (max-width:560px){
  .hero-grid{grid-template-columns:1fr;grid-auto-rows:215px}
  .hero-card:first-child{grid-column:span 1}
  .cards-grid{grid-template-columns:1fr}
  .logo-box{font-size:16px}
  .status-msg h1{font-size:24px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *{transition:none !important}
}

body.script:
//
/* World News Desk CNN-style theme — vanilla JavaScript only.
   1) Mobile menu + search toggles, 2) back-to-top,
   3) breaking bar + DEVELOPING rail + hero / label rows / related
   posts via Blogger JSON feeds. */
(function () {
  'use strict';

  /* ----- Mobile menu toggle ----- */
  var navToggle = document.getElementById('navToggle');
  var mainNav = document.getElementById('mainNav');
  if (navToggle && mainNav) {
    navToggle.addEventListener('click', function () {
      var open = mainNav.classList.toggle('open');
      navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  /* ----- Search overlay toggle ----- */
  var searchBtn = document.getElementById('searchBtn');
  var searchOverlay = document.getElementById('searchOverlay');
  var searchClose = document.getElementById('searchClose');
  function setSearch(open) {
    if (!searchOverlay) { return; }
    searchOverlay.classList.toggle('open', open);
    searchOverlay.setAttribute('aria-hidden', open ? 'false' : 'true');
    if (open) {
      var q = searchOverlay.querySelector('input[name="q"]');
      if (q) { q.focus(); }
    }
  }
  if (searchBtn) { searchBtn.addEventListener('click', function () { setSearch(true); }); }
  if (searchClose) { searchClose.addEventListener('click', function () { setSearch(false); }); }
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { setSearch(false); }
  });

  /* ----- Back to top ----- */
  var toTop = document.getElementById('toTop');
  if (toTop) {
    window.addEventListener('scroll', function () {
      toTop.classList.toggle('show', window.scrollY > 600);
    }, { passive: true });
    toTop.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  /* ----- Blogger JSON feed helpers ----- */
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function postUrl(entry) {
    var links = entry.link || [];
    for (var i = 0; i < links.length; i++) {
      if (links[i].rel === 'alternate') { return links[i].href; }
    }
    return '#';
  }
  function thumbUrl(entry, size) {
    var t = entry.media$thumbnail;
    if (t && t.url) { return t.url.replace(/\/s\d+(-c)?\//, '/s' + size + '/'); }
    /* Fallback: Blogger only puts media$thumbnail in the feed for images it
       hosts itself. Images inserted by URL (e.g. Wikimedia) have no thumbnail,
       so take the first image straight from the post body instead. */
    var c = entry.content && entry.content.$t ? entry.content.$t : '';
    var m = c.match(/<img[^>]+src=["']([^"']+)["']/);
    return m ? m[1] : '';
  }
  function postLabel(entry) {
    var cats = entry.category || [];
    return cats.length ? cats[0].term : '';
  }
  function fmtDate(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) { return ''; }
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }
  function fmtTimeAgo(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) { return ''; }
    var mins = Math.max(0, Math.round((Date.now() - d.getTime()) / 60000));
    if (mins < 60) { return mins + ' min ago'; }
    var hrs = Math.round(mins / 60);
    if (hrs < 24) { return hrs + ' hr ago'; }
    return fmtDate(iso);
  }
  var PH_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="#cc0000" stroke-width="1.5" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20M7 4v5M17 4v5M7 15v5M17 15v5"/></svg>';
  function thumbHtml(entry, size) {
    var src = thumbUrl(entry, size);
    if (src) {
      return '<img src="' + esc(src) + '" alt="' + esc(entry.title.$t) + '" loading="lazy" decoding="async"/>';
    }
    return '<div class="thumb-ph" aria-hidden="true">' + PH_SVG + '</div>';
  }
  function cardHtml(entry) {
    var url = postUrl(entry);
    var label = postLabel(entry);
    var chip = label ? '<span class="card-chips"><span class="card-chip">' + esc(label) + '</span></span>' : '';
    return '<article class="card">'
      + '<a class="card-thumb" href="' + esc(url) + '">' + thumbHtml(entry, 800) + chip + '</a>'
      + '<div class="card-info"><h3 class="card-title"><a href="' + esc(url) + '">' + esc(entry.title.$t) + '</a></h3>'
      + '<p class="card-date">' + esc(fmtDate(entry.published.$t)) + '</p></div>'
      + '</article>';
  }
  function heroHtml(entry) {
    var url = postUrl(entry);
    var label = postLabel(entry);
    var chip = label ? '<span class="hero-chip">' + esc(label) + '</span>' : '';
    return '<article class="hero-card">'
      + '<a href="' + esc(url) + '">' + thumbHtml(entry, 1600)
      + '<div class="hero-shade"></div>'
      + '<div class="hero-info">' + chip
      + '<h3>' + esc(entry.title.$t) + '</h3>'
      + '<p class="hero-date">' + esc(fmtDate(entry.published.$t)) + '</p>'
      + '</div></a></article>';
  }
  function fetchFeed(url, done) {
    fetch(url).then(function (r) {
      if (!r.ok) { throw new Error('feed ' + r.status); }
      return r.json();
    }).then(function (data) {
      done(data && data.feed && data.feed.entry ? data.feed.entry : []);
    }).catch(function () { done([]); });
  }

  /* Breaking bar: TV-style scrolling ticker of the latest headlines */
  var breakingTrack = document.getElementById('breakingTrack');
  if (breakingTrack) {
    fetchFeed('/feeds/posts/default?alt=json&max-results=5', function (entries) {
      if (!entries.length) { breakingTrack.innerHTML = '<span class="ticker-group"><a class="breaking-link" href="/">Top stories from around the globe.</a></span>'; return; }
      var esc = function (s) { return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
      var items = entries.slice(0, 5); /* exactly the top 5 latest titles, one after another, nonstop */
      var group = '<span class="ticker-group">' + items.map(function (e) {
        return '<a class="breaking-link" href="' + postUrl(e) + '">' + esc(e.title.$t) + '</a><span class="ticker-sep">&#8226;</span>';
      }).join('') + '</span>';
      breakingTrack.innerHTML = group + group;
    });
  }

  /* DEVELOPING rail: 5 most recent posts with time */
  var devBox = document.getElementById('developingBox');
  if (devBox) {
    fetchFeed('/feeds/posts/default?alt=json&max-results=5', function (entries) {
      var list = devBox.querySelector('.dev-list');
      if (!list || !entries.length) { return; }
      list.innerHTML = entries.map(function (e, i) {
        var flag = i === 0 ? '<span class="breaking-flag">Breaking News: </span>' : '';
        return '<li><span class="dev-time">' + esc(fmtTimeAgo(e.published.$t)) + '</span>'
          + '<span class="dev-title">' + flag + '<a href="' + esc(postUrl(e)) + '">' + esc(e.title.$t) + '</a></span></li>';
      }).join('');
    });
  }

  /* Hero: 5 most recent posts */
  var hero = document.getElementById('heroRow');
  if (hero) {
    fetchFeed('/feeds/posts/default?alt=json&max-results=5', function (entries) {
      if (!entries.length) { return; }
      hero.querySelector('.hero-grid').innerHTML = entries.map(heroHtml).join('');
      hero.classList.add('ready');
    });
  }

  /* Label rows (World / US / Politics / Business / Technology / Sports) */
  document.querySelectorAll('.label-row[data-label]').forEach(function (row) {
    var label = row.getAttribute('data-label');
    var max = row.getAttribute('data-max') || '4';
    fetchFeed('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + max, function (entries) {
      if (!entries.length) { return; }
      row.querySelector('.row-grid').innerHTML = entries.map(cardHtml).join('');
      row.classList.add('ready');
    });
  });

  /* Related posts: same first label as this post, excluding the current post */
  var related = document.getElementById('relatedBox');
  if (related) {
    var firstLabel = related.querySelector('.rel-label');
    if (firstLabel) {
      var label = firstLabel.getAttribute('data-label');
      var here = window.location.href.split('#')[0].replace(/\/$/, '');
      fetchFeed('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=5', function (entries) {
        var others = entries.filter(function (e) {
          return postUrl(e).split('#')[0].replace(/\/$/, '') !== here;
        }).slice(0, 4);
        if (!others.length) { return; }
        related.querySelector('.row-grid').innerHTML = others.map(cardHtml).join('');
        related.classList.add('ready');
      });
    }
  }
  /* Hide the duplicate cover inside the post body (the hero above already shows it) */
  (function () {
    var heroImg = document.querySelector('.post-hero img');
    var body = document.querySelector('.post-body');
    if (!heroImg || !body) { return; }
    var norm = function (u) { return (u || '').replace(/\/s\d+(-c)?\//, '/').replace(/\/w\d+(-h\d+)?\//, '/'); };
    var heroSrc = norm(heroImg.getAttribute('src'));
    var firstImg = body.querySelector('img');
    if (firstImg && norm(firstImg.getAttribute('src')) === heroSrc) {
      var wrap = firstImg.closest('div');
      if (wrap && wrap !== body) { wrap.style.display = 'none'; }
    }
  })();

})();
//
